		weight := n * reflect(n)
		if weight > maxWeight {
			maxWeight = weight
		}
	}

	fmt.Println(maxWeight)
}

func reflect(n int64) int64 {
	s := strconv.FormatInt(n, 10)
	reflected := ""
	for _, c := range s {
		digit := int(c - '0')
		reflected += strconv.Itoa(9 - digit)
	}
	// Remove leading zeros
	reflected = trimLeadingZeros(reflected)
	if reflected == "" {
		return 0
	}
	result, _ := strconv.ParseInt(reflected, 10, 64)
	return result
}

func trimLeadingZeros(s string) string {
	i := 0
	for i < len(s) && s[i] == '0' {
		i++
	}
	return s[i:]
}
